const {chromium}=require('playwright');const U='http://localhost:8765/';
(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1280,height:1000}});const errs=[];p.on('pageerror',e=>errs.push(e.message));
const ok=(n,c)=>console.log((c?'PASS ':'FAIL ')+n);
await p.goto(U+'?lang=ar#/patient');await p.evaluate(()=>{localStorage.clear();localStorage.setItem('kafila-entry','1');localStorage.setItem('screenpath-tour','{"open":false}');localStorage.setItem('screenpath-demo-ui','1')});await p.reload();await p.waitForTimeout(700);
await p.evaluate(()=>{Store.S.data.lang='ar';Store.save()});await p.waitForTimeout(200);
await p.click('[data-act="lock"]').catch(()=>{});await p.click('[data-act="openapp"]');await p.waitForTimeout(1400);await p.click('[data-act="consent"]').catch(()=>{});await p.click('[data-act="signin"]').catch(()=>{});await p.waitForTimeout(300);
await p.evaluate(()=>Patient.tourBook());await p.waitForTimeout(300);
await p.click('[data-act="tab"][data-arg="mycase"]').catch(()=>{});await p.waitForTimeout(300);
const t=await p.locator('.phone .screen, .phone').first().innerText();
const latin=(t.match(/\b(Dr\.|Centre|Clinic|Coordinator|Nurse)[^\n]{0,30}/g)||[]);ok('AR My case: no English names '+JSON.stringify(latin),latin.length===0);
ok('AR clinic name',!/خليفة سيتي/.test(await p.content()));
const f=await p.evaluate(()=>{const C=Store.S.C;const g=C.faq.find(x=>x.id==='a1c_diet');return [g.ar_f.includes('اشربي')&&g.ar_f.includes('اختاري'),['hpv_privacy','a1c_medicine','a1c_serious'].every(id=>!C.faq.find(x=>x.id===id).c)]});
ok('a1c_diet feminine',f[0]);ok('no empty compared-with',f[1]);
const sms=await p.evaluate(()=>I18N.ar.sms);ok('AR SMS STOP',/STOP/.test(sms));
await p.selectOption('#persona','C-1045');await p.waitForTimeout(400);
await p.evaluate(()=>{const c=Store.byId('C-1045');c.lang='ar';Store.save()});await p.waitForTimeout(200);
const ah=await p.evaluate(()=>document.querySelector('.phone').innerHTML);
ok('Ahmed: GP masculine',!/طبيبة الأسرة/.test(ah));
await p.setViewportSize({width:390,height:800});await p.goto(U+'#/case/C-1043');await p.waitForTimeout(500);
ok('BUG-29 case page fits phone',await p.evaluate(()=>document.documentElement.scrollWidth<=391));
console.log('errors',errs);await b.close()})();
